struct AnyViewsWatchData {
    jvm: jni::JavaVM,
    callback: GlobalRef,
}

unsafe extern "C" fn anyviews_watch_call(
    data: *mut (),
    ids: crate::array::WuiArray<crate::id::WuiId>,
    metadata_ptr: *mut crate::reactive::WuiWatcherMetadata,
) {
    // Always release callback payloads from Rust watcher bridge.
    ids.consume();
    if !metadata_ptr.is_null() {
        unsafe { drop(Box::from_raw(metadata_ptr)) };
    }

    debug_assert!(
        !data.is_null(),
        "anyviews_watch_call received null callback payload"
    );
    let watcher_data = unsafe { &*(data as *const AnyViewsWatchData) };

    let mut env = watcher_data
        .jvm
        .attach_current_thread()
        .expect("anyviews_watch_call: failed to attach current thread to JVM");
    env.call_method(&watcher_data.callback, "run", "()V", &[])
        .expect("anyviews_watch_call: Java callback run() failed");
}

unsafe extern "C" fn anyviews_watch_drop(data: *mut ()) {
    if !data.is_null() {
        unsafe {
            let _: Box<AnyViewsWatchData> = Box::from_raw(data as *mut AnyViewsWatchData);
        }
    }
}

