    let value: waterui::Str = unsafe { data.value.into_rust() };
    let jvalue = env
        .new_string(value.as_str())
        .expect("Failed to create DragDataStruct.value string");

    let class = env
        .find_class("dev/waterui/android/components/DragDataStruct")
        .expect("DragDataStruct class not found");
    env.new_object(
        &class,
        "(Ldev/waterui/android/components/DragDataTag;Ljava/lang/String;)V",
        &[JValue::Object(&tag_obj), JValue::Object(&jvalue)],
    )
    .expect("Failed to create DragDataStruct")
